// Try to redirect fullscreen target to a shared container
video.addEventListener('click', () => {
  sharedContainer.requestFullscreen(); // fails: content script isolated world, page CSP blocks override, user gesture consumed
});

cases.good:
// Let player's chosen element be fullscreenElement, move panel INTO it
fullscreenEl.addEventListener('fullscreenchange', () => {
  if (document.fullscreenElement) {
    fullscreenEl.appendChild(panel);
    fullscreenEl.style.display = 'flex'; // video + panel side-by-side
  } else {
    originalParent.appendChild(panel); // restore on exit
  }
});

// Fallback to fixed overlay when fullscreen element is <video>
if (document.fullscreenElement.tagName === 'VIDEO') {
  panel.style.cssText = 'position:fixed;right:0;top:0;width:30vw;height:100vh;z-index:2147483647';
} else {
  fullscreenEl.appendChild(panel); // container can host siblings
}
